import 'package:aqarat_app/features/buyer/data/datasources/buyer_remote_datasource.dart';
import 'package:aqarat_app/features/buyer/domain/repositories/buyer_repository.dart';
class BuyerRepositoryImpl implements BuyerRepository { const BuyerRepositoryImpl(this._remote); final BuyerRemoteDataSource _remote;
  @override Future<List<Map<String, dynamic>>> favorites() => _remote.favorites(); @override Future<Map<String, dynamic>> toggleFavorite(int id) => _remote.toggleFavorite(id); @override Future<List<Map<String, dynamic>>> bookings() => _remote.bookings(); @override Future<Map<String, dynamic>> createBooking({required int propertyId, required DateTime requestedFor, String? message}) => _remote.createBooking({'property_id': propertyId, 'requested_for': requestedFor.toIso8601String(), if (message != null && message.isNotEmpty) 'message': message}); @override Future<Map<String, dynamic>> cancelBooking(int id) => _remote.cancelBooking(id); @override Future<List<Map<String, dynamic>>> leads() => _remote.leads(); @override Future<Map<String, dynamic>> createLead({required String purpose, required String region, required num budget, required int rooms, required String details, int? propertyId}) => _remote.createLead({'purpose': purpose, 'region': region, 'budget': budget, 'rooms': rooms, 'details': details, if (propertyId != null) 'property_id': propertyId}); @override Future<List<Map<String, dynamic>>> notifications() => _remote.notifications(); @override Future<void> markNotificationsRead() => _remote.markNotificationsRead(); @override Future<Map<String, dynamic>> account() => _remote.account(); @override Future<Map<String, dynamic>> updateAccount({required String fullName, String? currentPassword, String? newPassword}) => _remote.updateAccount({'full_name': fullName, if (currentPassword != null) 'current_password': currentPassword, if (newPassword != null) 'new_password': newPassword}); @override Future<void> deleteAccount({required String currentPassword}) => _remote.deleteAccount(currentPassword); }
